"""Aplicar desde la raiz: python optimizar_rendimiento_panel.py

No se conecta a internet ni solicita credenciales. Conserva las formulas.
"""
import ast
import base64
from datetime import datetime
import hashlib
import json
from pathlib import Path
import shutil
import tempfile
import zlib

PAQUETE = ''


def leer(ruta):
    contenido = ruta.read_bytes()
    if contenido.startswith((b'\xff\xfe\x00\x00', b'\x00\x00\xfe\xff')):
        return contenido.decode('utf-32').replace('\r\n','\n')
    if contenido.startswith((b'\xff\xfe', b'\xfe\xff')):
        return contenido.decode('utf-16').replace('\r\n','\n')
    return contenido.decode('utf-8-sig').replace('\r\n','\n')


def huella(texto):
    return hashlib.sha256(texto.encode('utf-8')).hexdigest()


def escribir(ruta, contenido):
    ruta.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(dir=ruta.parent, delete=False) as temporal:
        nombre = Path(temporal.name)
        temporal.write(contenido)
    try:
        nombre.replace(ruta)
    finally:
        nombre.unlink(missing_ok=True)


def main():
    datos = json.loads(zlib.decompress(base64.b64decode(PAQUETE)))
    raiz = Path(__file__).resolve().parent
    if not (raiz / 'backend/app/main.py').is_file():
        raise ValueError('Coloca este archivo en la raiz del proyecto, junto a las carpetas backend y frontend.')
    pendientes = []
    # Revisar TODOS los archivos antes de modificar cualquiera.
    for relativo, nuevo in datos['nuevo'].items():
        ast.parse(nuevo, filename=relativo)
        ruta = raiz / relativo
        actual = leer(ruta) if ruta.exists() else None
        if actual == nuevo:
            continue
        esperado = datos['anterior'].get(relativo)
        if (esperado is None and actual is not None) or (esperado is not None and (actual is None or huella(actual) != esperado)):
            raise ValueError(f'No se modifico ningun archivo: {relativo} es distinto de la version revisada. Adjuntalo para adaptar la correccion.')
        pendientes.append((relativo, ruta, nuevo))
    if not pendientes:
        print('La optimizacion ya esta instalada. No se modifico ningun archivo.')
        return
    respaldo = raiz.parent / 'Respaldos_Agente_Camas' / ('rendimiento_' + datetime.now().strftime('%Y%m%d_%H%M%S_%f'))
    respaldo.mkdir(parents=True)
    originales = {}
    for relativo, ruta, _ in pendientes:
        originales[relativo] = ruta.read_bytes() if ruta.exists() else None
        if ruta.exists():
            destino = respaldo / relativo
            destino.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(ruta, destino)
    (respaldo / 'archivos_nuevos.json').write_text(json.dumps([r for r,v in originales.items() if v is None]), encoding='utf-8')
    escritos = []
    try:
        for relativo, ruta, nuevo in pendientes:
            escritos.append((relativo, ruta))
            escribir(ruta, nuevo.encode('utf-8'))
    except BaseException:
        for relativo, ruta in reversed(escritos):
            if originales[relativo] is None:
                ruta.unlink(missing_ok=True)
            else:
                escribir(ruta, originales[relativo])
        raise
    print('Optimizacion instalada: sin espera global por los tres datasets.')
    print('Modelos y evaluacion se calculan cuando se solicitan, no todos al arrancar.')
    print('Se reutilizan proyecciones repetidas y se evita entrenar lo mismo simultaneamente.')
    print('Cache acotada por proceso; los censos manuales no se guardan en ella.')
    print('Se conservaron formulas, validaciones, graficos, cuentas y permisos.')
    print('La primera consulta de una fecha nueva y la evaluacion aun pueden tardar.')
    print('Archivos cambiados:')
    for relativo, _, _ in pendientes:
        print(' - ' + relativo)
    print('Respaldo: ' + str(respaldo))
    print('Reinicia Uvicorn para probar. Render cambiara despues de commit, push y despliegue.')


if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        print('No se completo la instalacion: ' + str(error))
        raise SystemExit(1)
